window.MONSTER_CHUNK_26 = [{"name":"Fellsig","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"undead","subtypes":["fire"],"init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"30 ft."}],"ac":15,"ac_touch":10,"ac_flat_footed":15,"ac_mods":"+5 natural","hp":27,"hd":"5d8+5","hdvalue":5,"fort":2,"ref":1,"will":5,"defensive_abilities":["molten heart"],"immunities":["fire","undead traits"],"weaknesses":["vulnerable to cold"],"speed":[{"type":"land","speed":20}],"melee":"slam +6 (1d4+4 plus burn)","ranged":"lava ball +3 ranged touch (1d6 fire plus burn)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"burn","details":"1d6, DC 13"},{"type":"eruption"},{"type":"lava ball"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"burning hands"}]},{"frequency":"5/day","spells":[{"spell":"pyrotechnics"}]}],"strength":16,"dexterity":10,"intelligence":8,"wisdom":13,"charisma":12,"baseatk":3,"cmb":6,"cmb_special":"+2 vs. bull rush","cmd":16,"cmd_special":"+2 vs. bull rush","feats":[{"feat":"Blind-Fight"},{"feat":"Improved Bull Rush"},{"feat":"Power Attack"}],"skills":[{"skill":"Craft (any)","value":6},{"skill":"Intimidate","value":9},{"skill":"Perception","value":9}],"languages":["Dwarven","Ignan"],"environments":["any mountains","any underground"],"organizations":["solitary","pair","flow (3-8)"],"treasure":"standard","description_visual":"This squat figure's rough-hewn visage is frozen in a mask of pain, while the cracks in its dark stone body glow with a fiery inner heat.","source":"Andoran Birthplace Of Freedom","special_abilities":[{"type":"Lava Ball","kind":"Su","details":"As a full-round action, a fellsig can regurgitate a ball of lava into its fist and hurl it with a range increment of 30 ft. Any creature struck must succeed at a DC 13 Reflex save or catch fire and take 1d6 points of fire damage at the start of its turn for an additional 1d4 rounds. The save DC is Charisma-based."},{"type":"Molten Heart","kind":"Ex","details":"Beneath the slabs of igneous rock that compose a fellsig's body are organs of superheated rock and fumes. A creature that confirms a critical hit against a fellsig in melee is struck by a jet of flaming ash that deals 2d6 points of fire damage (Reflex DC 13 half)."}],"description":"First created in catastrophic event known as the Rending, the molten undead known as fellsigs have wandered Darkmoon Vale for centuries. When Droskar's Crag erupted and buried entire dwarven settlements under choking ash, boiling mud, noxious fumes, and seething magma, the violence and suffering caused many of the\n\nvolcano's victims to rise after death, cursed to visit their own fiery deaths upon the living. Fellsigs are made up of the very materials that took their lives, and their existence is a constant reminder of all that was lost in the fiery cataclysm of the Rending. Most fellsigs are morose creatures, bemoaning the destruction of their homeland and carrying on a shadowy imitation of their former lives amid the scorched ruins they inhabit. The sight of life and joy often enrages them with vindictive jealousy for those spared the fellsigs' own cruel fate.\n\nFellsigs have sympathy for those exhibiting obvious signs of burn damage, however, and using the Diplomacy skill can sometimes convince these stony, smoldering monsters to aid such creatures. Similarly, fellsigs hold no special hatred for creatures of the fire subtype, and on occasion they can be convinced to serve such creatures as guards or even artisans, though such alliances are tenuous at best.","ecology":"","habitat_society":""},{"name":"Fey Giant Toad","cr":3,"xp":800,"alignment":"CN","size":"Large","type":"fey","init":3,"senses":[{"type":"low-light vision"},{"type":"scent"}],"ac":15,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+3 Dex, +3 natural, -1 size","hp":22,"hd":"3d8+9","hdvalue":3,"fort":6,"ref":8,"will":0,"save_mods":"+4 vs. mind-affecting effects","defensive_abilities":["poison skin"],"dr":"5/cold iron","resists":[{"type":"cold","value":10},{"type":"electricity","value":10}],"speed":[{"type":"land","speed":30},{"type":"fly","speed":45,"maneuverability":"good"},{"type":"swim","speed":15}],"melee":"bite +4 (1d6+4 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"swallow whole","details":"1d4 bludgeoning damage, AC 11, 2 hp"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"entangle"},{"spell":"faerie fire"},{"spell":"glitterdust"}]},{"frequency":"3/day","spells":[{"spell":"dancing lights"}]}],"strength":17,"dexterity":17,"constitution":16,"intelligence":3,"wisdom":8,"charisma":8,"baseatk":2,"cmb":6,"cmb_special":"+4 vs. grapple","cmd":19,"cmd_special":"+4 vs. trip","feats":[{"feat":"Lightning Reflexes"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Acrobatics","value":11,"special":"+15 when jumping"},{"skill":"Fly","value":9},{"skill":"Perception","value":7},{"skill":"Stealth","value":8},{"skill":"Swim","value":11}],"languages":["Sylvan"],"sq":[{"type":"vanish","details":"3 rounds/day"}],"environments":["any plains","any swamps","temperate forests"],"organizations":["solitary","pair","knot (3-12)"],"treasure":"none","description_visual":"Little about this enormous toad is ordinary, from its graceful wings to its colorful purple and pink skin to its bright, shining eyes.","group":"Fey Creature","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Poison Skin","kind":"Ex","details":"A creature that strikes a fey giant toad with an unarmed strike or natural weapon exposes itself to the toad's poisonous skin. Skin-contact; save Fort DC 14; frequency 1/round for 4 rounds; effect 1d2 Wisdom damage; cure 1 save."}],"description":"Fey creatures resemble the mundane creatures they derive from, but with brighter colors, delicate features, and elegant wings such as those of a pixie or sprite. Despite their fragile-seeming appearance, fey creatures are every bit as hardy as their non-fey relations, though they sacrifice raw might for grace and the ability to fly. They live long lives, barring death by misadventure, and rarely show outward signs of age.\n\nSome fey creatures owe their nature to fey ancestors interbreeding with mortal beings, while others are races in their own right. Still others began life as ordinary creatures and were infused with fey essence through the magic of learned spellcasters or the inf luence of ancient powers of nature. As a rule, fey creatures rarely dwell in civilized lands, both by preference and because the conditions that give rise to the fey rarely occur in urban surroundings. If not already born into realms of primeval wild or areas touched by great fey powers, fey creatures soon seek them out.\n\nThough more prone to mischief than mayhem, fey creatures run the gamut from inimical to sprightly in behavior. Those inclined toward play and jest take a dim view of interlopers lacking in good humor. Such foul-tempered intruders risk humiliation at best if they insult the fey, and much worse if they raise arms against them. More aggressive fey still possess a well-developed though sadistic sense of humor. Such wicked fey use their inborn powers to lure outsiders to their doom, rather than into mere inconvenience.\n\nFey creatures generally have cordial relationships with animals, allies of nature such as druids, and other fey. Exceptions exist where rival communities of fey dwell in proximity to one another. In these cases, any fey creatures in the vicinity ally with one side or the other according to their own inclinations, only rarely standing outside such conflicts. Fey creatures derived from horses and the like often serve as mounts, though only to other fey or to allies of nature who acknowledge them as at least near-equals, if not full partners.","ecology":"","habitat_society":""},{"name":"Fey Wolverine","cr":3,"xp":800,"alignment":"CN","size":"Medium","type":"fey","subtypes":["augmented animal"],"init":4,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"low-light vision"},{"type":"scent"}],"ac":17,"ac_touch":14,"ac_flat_footed":13,"ac_mods":"+4 Dex, +3 natural","hp":22,"hd":"3d8+9","hdvalue":3,"fort":5,"ref":7,"will":3,"dr":"5/cold iron","sr":14,"speed":[{"type":"land","speed":40},{"type":"burrow","speed":20},{"type":"climb","speed":20}],"melee":"bite +4 (1d4+2), 2 claws +4 (1d6+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"death curse","details":"DC 13"},{"type":"rage"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"1/day","spells":[{"spell":"charm person"},{"spell":"faerie fire"}]}],"strength":15,"dexterity":19,"constitution":15,"intelligence":12,"wisdom":14,"charisma":14,"baseatk":2,"cmb":4,"cmd":18,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Bluff)"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":10},{"skill":"Bluff","value":12},{"skill":"Climb","value":16},{"skill":"Knowledge (nature)","value":7},{"skill":"Perception","value":8},{"skill":"Sense Motive","value":8},{"skill":"Stealth","value":14}],"languages":["Skald","Sylvan"],"environments":["cold forests"],"organizations":["solitary"],"treasure":"none","description_visual":"This wolverine's eyes possess the unmistakable glint of intelligence, and its mouth seems to twitch as if it were about to laugh.","group":"Fey Animal","source":"Lands Of The Linnorm Kings","ecology":"","habitat_society":""},{"name":"Flind","cr":3,"xp":800,"alignment":"NE","size":"Medium","type":"humanoid","subtypes":["gnoll"],"init":6,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+3 armor, +2 Dex, +2 natural","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":3,"will":3,"speed":[{"type":"land","speed":30}],"melee":"flindbar +6 (1d8+6/x2 plus disarm, trip)","ranged":"composite longbow +5 (1d8+4/x3)","space":"5 ft.","reach":"5 ft.","strength":18,"dexterity":15,"constitution":16,"intelligence":12,"wisdom":15,"charisma":13,"baseatk":3,"cmb":7,"cmd":19,"feats":[{"feat":"Improved Initiative"},{"feat":"Power Attack"}],"skills":[{"skill":"Handle Animal","value":8},{"skill":"Intimidate","value":5},{"skill":"Perception","value":6}],"languages":["Common","Gnoll"],"sq":[{"type":"weapon familiarity"}],"environments":["any deserts","warm plains"],"organizations":["solitary","pair","hunting party (1 flind, 1-4 gnolls and 1-2 hyenas)","band (10-100 gnolls [30% flinds and 50% noncombatant children], 1 sergeant of 3rd level per 20 adults, 1 leader of 4th-6th level, and 5-8 hyenas)","tribe (20-200 gnolls [30% flinds and 50% noncombatant children] plus 1 sergeant of 3rd level per 20 gnolls, 1 or 2 lieutenants of 4th or 5th level, 1 leader of 6th-8th level, 7-12 hyenas, and 4-7 hyaenodons)"],"treasure":"standard (studded leather, composite longbow [Str +4] with 20 arrows, flindbar)","description_visual":"This powerfully built, hyena-like humanoid is larger than the average gnoll and has a cunning, cruel gaze.","source":"Monster Codex","special_abilities":[{"type":"Weapon Familiarity","details":"Flinds are always proficient with flindbars."}],"description":"Flinds are slightly larger, more intelligent, and of a stockier build than gnolls, and it's a common misconception that flinds are an entirely separate race. Though interbreeding may one day make them so, flinds are actually the product of controlled breeding practices by the dominant females of gnoll packs.\n\nThe slyest and largest female gnolls sanctified by the chosen of Lamashtu are paired with the most savage males, and a little more than half the time, the resulting litter includes at least one flind. The flind pup is often female. A breeding female flind produces only flinds, though flinds' litters tend to be smaller than those of normal gnolls. Male flinds who breed with female gnolls produce a litter with a flind about three quarters of the time.\n\nMore capable of focus, cunning, and planning than gnolls, flinds are typically found in leadership roles within gnoll bands and tribes, and frequently lead hunting parties. Like gnolls, flinds use ambush tactics and often make slaves of surviving foes, yet a flind is more likely to go on the offensive when the odds are closer to even. Flinds still prefer the advantage of attacking in numbers-they just don't need the advantage to be overwhelming. In addition to using intimidation against enemies, flinds embrace flanking tactics and specialized uses of their unusual weapon, the flindbar.\n\nFlinds assign gnolls lower in the pack hierarchy the task of crafting flindbars. Flinds are very particular about these weapons, and a gnoll who fails to properly weight and polish a flindbar can expect a savage mauling from the flind who demanded the weapon.\n\nA flind is roughly 7 ft. tall and weighs between 280 and 315 pounds. Flinds have brindled or spotted fur, and are primarily russet in color with patches of black.","ecology":"","habitat_society":""},{"name":"Formian Warrior","cr":3,"xp":800,"alignment":"LN","size":"Medium","type":"monstrous humanoid","init":7,"init_special":"+11 with hive mind","senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."},{"type":"hive mind"}],"ac":17,"ac_touch":13,"ac_flat_footed":14,"ac_mods":"+3 Dex, +4 natural","hp":30,"hd":"4d10+8","hdvalue":4,"fort":3,"ref":7,"will":4,"resists":[{"type":"sonic","value":10}],"speed":[{"type":"land","speed":40}],"melee":"sting +6 (1d4+2 plus poison), 2 claws +6 (1d4+2 plus grab)","ranged":"javelin +7 (1d6+2 plus poison)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"deadly grasp"},{"type":"poison"}],"strength":14,"dexterity":17,"constitution":15,"intelligence":11,"wisdom":10,"charisma":12,"baseatk":4,"cmb":6,"cmb_special":"+4 vs. grapple","cmd":19,"cmd_special":"+4 vs. trip","feats":[{"feat":"Skill Focus (Acrobatics)"},{"feat":"Step Up"}],"skills":[{"skill":"Acrobatics","value":10,"special":"+14 when jumping"},{"skill":"Climb","value":8},{"skill":"Intimidate","value":8},{"skill":"Perception","value":7,"special":"+11 with hive mind"},{"skill":"Stealth","value":7}],"languages":["Common","telepathy 60 ft."],"sq":[{"type":"coordinate"},{"type":"formian traits"}],"environments":["temperate land","any underground","warm land"],"organizations":["solitary","pair","band (5-8 plus 3-15 workers and 1 taskmaster)","patrol (3-12)"],"treasure":"standard (6 javelins)","description_visual":"Armored from head to toe in gleaming black-and-red chitin, this insectile warrior's tail ends in a wickedly barbed stinger.","group":"Formian","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Coordinate","kind":"Su","details":"Once a formian warrior has acted in a combat, all allied formians within the hive mind are no longer considered flat-footed. When a formian warrior attacks a creature in melee, allied formians gain a +2 insight bonus on melee attack rolls against that creature until the start of the warrior's next turn."},{"type":"Deadly Grasp","kind":"Ex","details":"When a formian warrior has a foe grappled, it deals sting damage when it succeeds at a grapple check to damage its opponent."},{"type":"Poison","kind":"Ex","details":"Javelin or sting-injury; save Fort DC 14; frequency 1/round for 6 rounds; effect 1d2 Dex; cure 1 save."}],"description":"Composing the fighting caste of the hive, formian warriors grow from grubs hatched in the flesh of carnivores and similar fierce creatures. All are sterile females, although in rare circumstances they spontaneously become fertile after the death of their queen. In the rigid hierarchy of the formian hive, they rank above the worker caste and below all others. Allowed independent initiative to better hone their battle skills, formian warriors have more latitude in following commands than many other formians. Owing to this latitude, formian warriors are more likely to chafe under hive strictures than workers and taskmasters. All formian warriors ultimately answer to the myrmarch caste and, through them, to the queen. Beneath this layer of command, the warriors have a command structure of their own. Formian warriors advance in rank through a complicated formula that references their achievements in battle, personal prowess, and years of service to the hive. Formian warriors engrave their chitin with insignia depicting their rank and notable deeds. A disgraced warrior has her markings gouged out and her stinger torn away. Formian warriors stand 7 ft. tall and weigh 200 pounds. Their carapaces resemble suits of armor as much as insects' exoskeletons but cannot be enhanced with magic as if they were armor. The striped patterns of a formian warrior vary from individual to individual, although formians belonging to the same hive usually bear similar markings. Warriors mature quickly and have short life spans, becoming too infirm to fight around 15 years of age. Old warriors are expected to end their lives for the good of the hive, either by taking on a fatal mission or through voluntary starvation. A few of the most exceptional warriors receive permission to live out their remaining years as teachers and drill instructors, passing their skills on to new generations of formian warriors.","ecology":"","habitat_society":""},{"name":"Four-armed","cr":3,"xp":800,"alignment":"LE","size":"Medium","type":"monstrous humanoid","subtypes":["aquatic"],"init":1,"senses":[{"type":"blindsense","modifier":"30 ft."},{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+1 Dex, +5 natural","hp":18,"hd":"2d10+7","hdvalue":2,"fort":4,"ref":4,"will":4,"weaknesses":["light blindness"],"speed":[{"type":"land","speed":30},{"type":"swim","speed":60}],"melee":"trident +4 (1d8+2), bite +2 (1d4+1), 2 claws +4 (1d4+2) or  bite +4 (1d4+1), 4 claws +4 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"blood frenzy"}],"strength":14,"dexterity":13,"constitution":14,"intelligence":14,"wisdom":13,"charisma":9,"baseatk":2,"cmb":4,"cmd":15,"feats":[{"feat":"Great Fortitude"},{"feat":"Multiattack","type":"bonus"},{"feat":"Toughness","type":"bonus"}],"skills":[{"skill":"Handle Animal","value":1},{"skill":"Perception","value":6},{"skill":"Ride","value":6},{"skill":"Stealth","value":6},{"skill":"Survival","value":6},{"skill":"Swim","value":15}],"languages":["Aquan","Common","speak with sharks"],"environments":["temperate oceans","warm oceans"],"organizations":["solitary","pair","unit (1 plus 3-18 sahuagin)","royal guard (2-8 plus 1 sahuagin chieftain of 4th level)"],"treasure":"none","description_visual":"This burly humanoid has sharp scales and fins like some predatory fish. As if its maw full of serrated teeth were not intimidating enough, the monstrosity clenches deadly claws at the ends of four powerful arms.","group":"Sahuagin Mutant","source":"AP 56","special_abilities":[{"type":"Blood Frenzy","kind":"Ex","details":"Once per day, a four-armed sahuagin that takes damage in combat can fly into a frenzy in the following round. It gains a +2 bonus to its Constitution and Strength, but takes a -2 penalty to its AC. The frenzy lasts as long as the battle or 1 minute, whichever is shorter."},{"type":"Multiweapon Mastery","kind":"Ex","details":"A four-armed sahuagin never takes penalties on attack rolls when fighting with multiple weapons, and treats claws as primary attacks even when also wielding weapons."},{"type":"Speak with Sharks","kind":"Su","details":"A four-armed sahuagin can communicate telepathically with sharks to a distance of 150 ft. This communication is limited to simple concepts, such as \"come here,\" \"defend me,\" or \"attack this target.\""}],"description":"The unpredictability and viciousness of the sahuagin race isn't just an aspect of their sharklike temperament- it seems to be inherent in their very beings. The unusual and typically deadly mutants common to the race attest to this, their forms altering and becoming more deadly based either on the needs of the community or ambiguous environmental factors. Whatever the case, sahuagin mutants often rise to positions of respect and inf luence in sahuagin communities, their innate advantages instantly placing them among their people's rulers. Of these mutants, four-armed sahuagin brutes and malenti- sahuagin with the appearances of sea elves-arise most commonly, though these are in no way the only sahuagin mutants known to the savage seas.\n\nSahuagin Alterations Both the four-armed sahuagin and the malenti use the stats presented on page 239 of the Bestiary as their foundations, with the following alterations. As sahuagin are such common menaces over the course of the Skull & Shackles Adventure Path, their variants are included here to make encounters with the shark people even more unpredictable and deadly.\n\nFour-Armed Sahuagin: These mutants gain Multiattack and Toughness as bonus feats and the multiweapon mastery ability. These changes don't include an increase in such a mutant's Hit Dice, but do increase its CR to 3. Despite the advantages these additions give the creature, its hit points are on the low side for a CR 3 monster. GMs should consider giving four-armed sahuagin armor considerably better than that usually worn by CR 3 monsters to make up for this relative glass jaw. Giving the creature leather armor (or an aquatic equivalent, such as shark leather armor) grants it a +2 armor bonus, increasing its AC to 18-above the average for its CR, but a considered benefit to help balance out its weakness. Four-armed sahuagin excel as barbarians, fighters, rangers, and warriors.\n\nMalenti: These mutants gain a +4 bonus to Dexterity and Charisma, Deceitful and Skill Focus (Bluff) as bonus feats, and command as a spell-like ability (representing increased telepathic inf luence over aquatic creatures). Additionally, a malenti's natural armor bonus decreases to +2 and the malenti loses its light blindness and natural weapons. The benefits a malenti gains largely offset those it loses, resulting in no change to the creature's CR. Malenti excel as bards, oracles, rogues, and wizards.\n\nOther Sahuagin Mutants Although four-armed sahuagin and malenti are the most common sahuagin mutants, they are not the only abnormalities to arise from sahuagin stock. The following mutants are also sometimes found in sahuagin societies. While rarer than other mutants, they too quickly garner the respect and fear of their piscine brethren.\n\nPrehistoric Sahuagin: Also known as adacthys, these sahuagin mutants are throwbacks to some even more savage epoch; they are Large, have a +7 natural armor bonus, and can speak with aquatic dinosaurs and megafauna in addition to sharks. They are usually found in the same waters as prehistoric creatures or waters that are somehow strangely affected by the flow of time.\n\nShark-Blooded Sahuagin: These sahuagin mutants have overly large maws filled with rows of sharklike teeth, and the fins and tail of an oversized thresher shark (or other local variety). These abnormalities give them the appearance of monstrous merfolk, a swim speed of 80 ft., and a bite attack that deals 1d6 points of damage. Shark-blooded sahuagin are most typically found in sahuagin communities with unusually high numbers of shark guardians and near shark breeding grounds.\n\nSpined Sahuagin: Covered in hundreds of needle-like spines, these sahuagin can raise these piercing protrusions to impale creatures that attempt to grab or consume them. Any creature that grapples a spined sahuagin takes 1d4 points of piercing damage. Additionally, these mutants gain Defensive Combat Training as a bonus feat. Spined sahuagin most commonly appear in depths that also serve as the hunting grounds of sea serpents, thalassic behemoths, or other massive aquatic predators.","ecology":"","habitat_society":"","gear":"trident"},{"name":"Freshwater Merrow","cr":3,"xp":800,"alignment":"NE","size":"Large","type":"humanoid","subtypes":["aquatic","giant"],"init":4,"senses":[{"type":"low-light vision"}],"ac":17,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+4 Dex, +4 natural, -1 size","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":5,"will":3,"speed":[{"type":"land","speed":40},{"type":"swim","speed":40}],"melee":"2 claws +6 (1d6+4 plus grab)","ranged":"javelin +6 (1d8+4)","space":"10 ft.","reach":"10 ft.","strength":19,"dexterity":18,"constitution":17,"intelligence":6,"wisdom":10,"charisma":7,"baseatk":3,"cmb":8,"cmb_special":"+4 vs. grapple","cmd":22,"feats":[{"feat":"Iron Will"},{"feat":"Power Attack"}],"skills":[{"skill":"Perception","value":5},{"skill":"Stealth","value":2,"special":"+6 in water"},{"skill":"Swim","value":12}],"languages":["Giant"],"sq":[{"type":"amphibious"}],"environments":["temperate lakes","temperate rivers"],"organizations":["solitary","pair","gang (3-4)","family (5-16)"],"treasure":"standard (2 javelins)","description_visual":"This giant has pale green, scaled skin and large, webbed hands and ft. On either side of its neck are slotted gills.","group":"Merrow","source":"PFRPG Bestiary 2","description":"Merrows are best described as the aquatic cousins of ogres. Although their green, scaled skin and webbed hands and ft. make them appear different, merrows are just as cruel, savage, and wicked as their ogre relatives. The saltwater variety grows much larger than the freshwater variety, but the behavior and society of the two types are otherwise similar. Merrows are known for pillaging small fishing villages and towns under cover of night. Similar to ogres, merrows have a strong sense of family and typically hunt in gangs, preferring to grab a couple of villagers and head back into the water rather than sticking around and dealing with armed resistance. Merrows have a stronger sense of unity than ogres do, and rarely will the leader of a tribe be challenged. When they have chosen a village or town to plunder, they attack as a gang and share the spoils. A freshwater merrow is 12 ft. tall and weighs 500 pounds. Saltwater merrows easily reach 20 ft. tall and 4,000 pounds, and have been known to hunt whales. The two species don't often come in contact, but when they do, feuding and conf lict are swift to develop.","ecology":"","habitat_society":""},{"name":"Fukujin","cr":3,"xp":800,"alignment":"LN","size":"Tiny","type":"outsider","subtypes":["kami","native"],"init":7,"senses":[{"type":"darkvision","modifier":"60 ft."}],"auras":["aura of luck (15 ft.)"],"ac":15,"ac_touch":15,"ac_flat_footed":12,"ac_mods":"+3 Dex, +2 size","hp":30,"hd":"4d10+8","hdvalue":4,"hp_mods":["fast healing 3"],"fort":6,"ref":4,"will":7,"dr":"5/cold iron or evil","immunities":["bleed","mind-affecting effects","petrification","polymorph"],"resists":[{"type":"acid","value":10},{"type":"electricity","value":10},{"type":"fire","value":10}],"speed":[{"type":"land","speed":30}],"melee":"short sword +7 (1d3+1/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"precise attacks"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"speak with plants"}]},{"frequency":"at-will","spells":[{"spell":"mending"},{"spell":"purify food and drink"}]},{"frequency":"1/day","spells":[{"spell":"delay poison"},{"spell":"goodberry"},{"spell":"soften earth and stone"}]},{"frequency":"3/day","spells":[{"spell":"detect snares and pits"},{"spell":"remove sickness"}]}],"strength":13,"dexterity":16,"constitution":14,"intelligence":11,"wisdom":17,"charisma":14,"baseatk":4,"cmb":5,"cmd":16,"feats":[{"feat":"Alertness"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Appraise","value":7},{"skill":"Bluff","value":9},{"skill":"Diplomacy","value":9},{"skill":"Knowledge (nature)","value":7},{"skill":"Perception","value":12},{"skill":"Sense Motive","value":12}],"languages":["Common","speak with plants","telepathy 100 ft."],"sq":[{"type":"merge with ward"},{"type":"ward","details":"bonsai trees and small plants"}],"environments":["any"],"organizations":["solitary","garden (2-4)"],"treasure":"standard","description_visual":"This diminutive humanoid looks like a truly ancient but proud old warrior. A tiny tree branch juts from the top of his head.","group":"Kami","source":"AP 52","special_abilities":[{"type":"Aura of Luck","kind":"Su","details":"A fukujin brings good fortune with it wherever it goes. Any allied creature that begins its turn within 15 ft. of a fukujin gains a +2 bonus on skill checks."},{"type":"Precise Attacks","kind":"Su","details":"A fukujin can detect weak points in a foe's defenses as an immediate action by succeeding at a DC 15 Perception check. Once these weak points have been determined, a fukujin gains a +2 bonus on attack rolls to confirm critical hits against that creature for 24 hours. A fukujin can inform a single ally within 30 ft. of its findings as a swift action, granting that ally the same bonus. This bonus cannot be granted to more than one creature, even if a fukujin attempts to point out a weakness to another."}],"description":"Spiritual guardians of ornamental shrubs and miniature trees, fukujin are highly regarded among Tians as bringers of good fortune and sound wisdom. Fukujins are thought to only come to goodhearted and devoted bonsai gardeners, and since bonsai plants are often only cultivated by astute and aesthetically minded humanoids, the kami are usually of a similar nature, speaking to mortals rarely and always cryptically. Regardless of how much of their coveted knowledge they impart upon favored mortals, however, fukujins always bring with them a sense of hope and good luck, and almost all within close proximity of the kami feel an instant sense of relief.\n\nFukujins resemble humanoids with tree branches protruding from their bodies, most often their heads, and some fukujins possess leafy hair or treelike limbs. A fukujin in its physical form is only as tall as its bonsai ward-usually only a foot or two-and weighs less than 30 pounds. Ecology\n\nWhile many see the art of bonsai gardening as humanoids' attempts at controlling or forming nature, fukujins ref lect the practice's virtues of patience and nurturing. Fukujins maintain that a moment of patience and study can reveal multitudes more than years of trial and error, and the diminutive beings spread this knowledge wherever they go. While kami don't reproduce in any typical sense, fukujins are known to sow seeds of bonsai plants in the wake of their footsteps, further delighting communities that appreciate such flora. Though assignment of kami remains up to the mysterious will of the gods, fukujins do their part in creating numerous hosts for these spirits.\n\nThe health and strength of the tree branch protruding from a fukujin's head is often said to be a good indicator of the skill of the warded bonsai tree's caretaker. While the aesthetic values of bonsai trees are often completely subjective, the kami spirits are evidence that there is perhaps a series of core doctrines bonsai farmers should adhere to when taking care of their plants-ideals that a gardener can strive toward to ensure he achieves success in his maintenance of the small tree. A poorly trimmed bonsai plant may sicken the spirit for a time, for instance, while expert grafting can result in a strong or knowledgeable kami. In most cases, however, a kami will almost always leave its ward if a bonsai gardener neglects the plant long enough or effectively ruins the effort, for though fukujins are patient, they have little tolerance for the virtues of negligence and wastefulness.\n\nWhile nearly all fukujins are calm, collected, and patient spirits, the beings are by no means all the same, as their physical appearances, predispositions, and demeanors are just as often reflections of the particular bonsai plant that they watch over. Fukujins who reside within the hearts of deciduous trees, for example, tend to be of lighter color as well as more airy and spirited than the hardy and resilient fukujins of coniferous shrubs, who take on a red, earthy hue. Plant type can also hint at particular magical qualities the spirit might have-white-trunked trees tend to attract gaunter, more fatalistic individuals, while plants with brown or ebon bark inspire kami that are more attuned to the energies and mysteries of magic. The tree branch that sticks out of a fukujin's head while the spirit is in its physical form is often of the same variety as the bonsai tree that the kami protects, though exceptions have been known to exist among particularly dual-natured spirits.\n\nHabitat & Society\n\nSince their wards are by nature the direct result of humanoid intervention, fukujins are naturally social creatures, and most seek to assist their humanoid partners in not only cultivating beautiful plants, but\n\nin all spheres of life. Many bonsai gardeners are often content to live in a permanent home, establish a family, and live a life of tranquility, and fukujins happily provide all manner of advice regarding these domestic issues. In other instances, however, fukujins have been known to travel alongside particularly adventurous cultivators, humanoids who keep the shrubbery and kami spirit in safe and comfortable packs or pouches and consult them for wisdom in circumstances both dire and unusual. The miniature kami's insights and good luck prove as useful in the heat of battle as in the hearthstone, and so humanoids from nearly all walks of life seek the favor of these beings.\n\nBonsai trees are delicate plants and their kami ref lect this fragility. What they lack in physical defenses, however, fukujins make up for in grace and keen insight, using their natural acumen to avoid and deter hazards before they're even encountered. Some might mistakenly see this expert passiveness as a manifestation of fukujins' philanthropic ideals and good intentions, but more often than not their flightiness is simply what they deem to be the wisest course of action. In situations where violence is inevitable, fukujins seek the aid of stronger individuals to help protect them, true to the tradition of their wards' reliance on humanoid intervention and maintenance. Rather than view this reliance on humanoids as a weakness, however, most fukujins accept it as part of a long-lasting transaction between the two forces, each providing unique benefits to the other throughout the relationship. To bolster this partnership, fukujins harness healing powers as well as the strength of their insight, ensuring that their caretakers remain healthy and able to protect the kami and their wards.\n\nWhile they almost always possess pertinent and useful advice, fukujins are known for being reserved under most circumstances, sharing what knowledge they have only when it is absolutely necessary, and they never share wisdom superfluously. Fukujins are normally individualistic and solitary like the plants they watch over, and when they interact with one another they usually do so telepathically. What people often perceive as the luck of fukujins is often merely the result of wise advice garnered from the spirits, though when asked if the kami really are bringers of fortune, fukujins are known to remain even more tight-lipped than usual.\n\nOccasionally one might encounter a fukujin in the wild, in lands far from the societies and plants where they commonly make their homes. In such cases, these miniature kami often claim shrubs, young plants, and even whimiscal-looking mushrooms as their wards, grooming nearby groves and glades into quiet meditation gardens or into artistic shapes, inviting visitors to rest and reflect.","ecology":"While many see the art of bonsai gardening as humanoids' attempts at controlling or forming nature, fukujins ref lect the practice's virtues of patience and nurturing. Fukujins maintain that a moment of patience and study can reveal multitudes more than years of trial and error, and the diminutive beings spread this knowledge wherever they go. While kami don't reproduce in any typical sense, fukujins are known to sow seeds of bonsai plants in the wake of their footsteps, further delighting communities that appreciate such flora. Though assignment of kami remains up to the mysterious will of the gods, fukujins do their part in creating numerous hosts for these spirits.\n\nThe health and strength of the tree branch protruding from a fukujin's head is often said to be a good indicator of the skill of the warded bonsai tree's caretaker. While the aesthetic values of bonsai trees are often completely subjective, the kami spirits are evidence that there is perhaps a series of core doctrines bonsai farmers should adhere to when taking care of their plants-ideals that a gardener can strive toward to ensure he achieves success in his maintenance of the small tree. A poorly trimmed bonsai plant may sicken the spirit for a time, for instance, while expert grafting can result in a strong or knowledgeable kami. In most cases, however, a kami will almost always leave its ward if a bonsai gardener neglects the plant long enough or effectively ruins the effort, for though fukujins are patient, they have little tolerance for the virtues of negligence and wastefulness.\n\nWhile nearly all fukujins are calm, collected, and patient spirits, the beings are by no means all the same, as their physical appearances, predispositions, and demeanors are just as often reflections of the particular bonsai plant that they watch over. Fukujins who reside within the hearts of deciduous trees, for example, tend to be of lighter color as well as more airy and spirited than the hardy and resilient fukujins of coniferous shrubs, who take on a red, earthy hue. Plant type can also hint at particular magical qualities the spirit might have-white-trunked trees tend to attract gaunter, more fatalistic individuals, while plants with brown or ebon bark inspire kami that are more attuned to the energies and mysteries of magic. The tree branch that sticks out of a fukujin's head while the spirit is in its physical form is often of the same variety as the bonsai tree that the kami protects, though exceptions have been known to exist among particularly dual-natured spirits.","habitat_society":"Since their wards are by nature the direct result of humanoid intervention, fukujins are naturally social creatures, and most seek to assist their humanoid partners in not only cultivating beautiful plants, but\n\nin all spheres of life. Many bonsai gardeners are often content to live in a permanent home, establish a family, and live a life of tranquility, and fukujins happily provide all manner of advice regarding these domestic issues. In other instances, however, fukujins have been known to travel alongside particularly adventurous cultivators, humanoids who keep the shrubbery and kami spirit in safe and comfortable packs or pouches and consult them for wisdom in circumstances both dire and unusual. The miniature kami's insights and good luck prove as useful in the heat of battle as in the hearthstone, and so humanoids from nearly all walks of life seek the favor of these beings.\n\nBonsai trees are delicate plants and their kami ref lect this fragility. What they lack in physical defenses, however, fukujins make up for in grace and keen insight, using their natural acumen to avoid and deter hazards before they're even encountered. Some might mistakenly see this expert passiveness as a manifestation of fukujins' philanthropic ideals and good intentions, but more often than not their flightiness is simply what they deem to be the wisest course of action. In situations where violence is inevitable, fukujins seek the aid of stronger individuals to help protect them, true to the tradition of their wards' reliance on humanoid intervention and maintenance. Rather than view this reliance on humanoids as a weakness, however, most fukujins accept it as part of a long-lasting transaction between the two forces, each providing unique benefits to the other throughout the relationship. To bolster this partnership, fukujins harness healing powers as well as the strength of their insight, ensuring that their caretakers remain healthy and able to protect the kami and their wards.\n\nWhile they almost always possess pertinent and useful advice, fukujins are known for being reserved under most circumstances, sharing what knowledge they have only when it is absolutely necessary, and they never share wisdom superfluously. Fukujins are normally individualistic and solitary like the plants they watch over, and when they interact with one another they usually do so telepathically. What people often perceive as the luck of fukujins is often merely the result of wise advice garnered from the spirits, though when asked if the kami really are bringers of fortune, fukujins are known to remain even more tight-lipped than usual.\n\nOccasionally one might encounter a fukujin in the wild, in lands far from the societies and plants where they commonly make their homes. In such cases, these miniature kami often claim shrubs, young plants, and even whimiscal-looking mushrooms as their wards, grooming nearby groves and glades into quiet meditation gardens or into artistic shapes, inviting visitors to rest and reflect."},{"name":"Fungal Crawler","cr":3,"xp":800,"alignment":"N","size":"Small","type":"aberration","init":9,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":16,"ac_touch":16,"ac_flat_footed":11,"ac_mods":"+5 Dex, +1 size","hp":26,"hd":"4d8+8","hdvalue":4,"fort":3,"ref":6,"will":5,"defensive_abilities":["plant defenses"],"immunities":["mind-affecting effects","paralysis","poison","polymorph effects","sleep","stunning"],"speed":[{"type":"land","speed":20},{"type":"climb","speed":40}],"melee":"bite +6 (1d6+2 plus poison), 2 claws +6 (1d4+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"leap"}],"strength":14,"dexterity":20,"constitution":15,"intelligence":2,"wisdom":13,"charisma":7,"baseatk":3,"cmb":4,"cmd":19,"cmd_special":"+8 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Step Up"}],"skills":[{"skill":"Acrobatics","value":10,"special":"+14 jumping"},{"skill":"Climb","value":10},{"skill":"Perception","value":6}],"environments":["any underground"],"organizations":["solitary","pair","swarm (3-12)"],"treasure":"none","description_visual":"This giant fanged cricket is caked in pungent fungal growths and topped with a mushroom-like cap.","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Leap","kind":"Ex","details":"A fungal crawler can perform a special kind of pounce attack by jumping into combat. When a fungal crawler charges, it can make a DC 20 Acrobatics check to jump into the air and land next to its enemies. If it makes the Acrobatics check, it can follow up with four claw attacks against foes in reach, but it cannot make a bite attack."},{"type":"Plant Defenses","kind":"Ex","details":"A fungal crawler is part plant and shares many of the immunities that plant creatures possess. A fungal crawler is immune to mind-affecting effects, paralysis, poison, polymorph, sleep, and stunning."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 14; frequency 1/ round for 4 rounds; effect 1d2 Str and 1d2 Con; cure 1 save. The save DC is Constitution-based."}],"description":"Fungal crawlers are a perverse fusion of animal and plant. Over thousands of years, they have prospered and spread beneath the world, dominating the wildest depths of these underground regions. Like hyenas, fungal crawlers are top-tier scavengers. They are efficient hunters, but just as often feed on found carrion or take meals from other predators. When times are especially lean, fungal crawlers can even survive without food, subsisting on radiation and heat absorbed through the fungal flutes covering their pale, sickly bellies.\n\nThousands of breeds of fungal crawlers exist across the world, varying in appearance and habits, but all share a few common features. They invariably appear as monstrous crickets or locusts fused with fungal growths, often topped with mushroom-like caps. This hybridization makes them adept survivors, and infestations are notoriously difficult to clear out entirely. Their needle-like teeth cannot chew solid food, so most fungal crawlers rely on digestive enzymes injected through their bite to make their meals palatable. Average specimens grow to 30 pounds and 3 ft. in length. They reproduce by releasing spores, which remain viable for decades until they contact organic matter and eventually develop into small, pale grubs.\n\nMany subterranean civilizations tame fungal crawlers as guard animals, pets, or food. Though simple-minded, they are amicable enough to be trained when well-fed. Fungal crawlers hold no loyalties, though, and often flee or attack their keepers at the slightest provocation.\n\nThanks to the bizarre energies that suffuse their homes, fungal crawlers are incredibly diverse. They have adapted over millennia to fill every environment: flying variants fill subterranean rifts with the deafening drone of their wings, while aquatic breeds skim across the surfaces of underground lakes, and still others thrive in the fiery chambers and tunnels of volcanic networks.","ecology":"","habitat_society":""},{"name":"Gelatinous Cube","cr":3,"xp":800,"alignment":"N","size":"Large","type":"ooze","init":-5,"senses":[{"type":"blindsight","modifier":"60 ft."}],"ac":4,"ac_touch":4,"ac_flat_footed":4,"ac_mods":"-5 Dex, -1 size","hp":50,"hd":"4d8+32","hdvalue":4,"fort":9,"ref":-4,"will":-4,"immunities":["electricity","ooze traits"],"speed":[{"type":"land","speed":15}],"melee":"slam +2 (1d6 plus 1d6 acid)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"engulf"},{"type":"paralysis"}],"strength":10,"dexterity":1,"constitution":26,"wisdom":1,"charisma":1,"baseatk":3,"cmb":4,"cmd":9,"cmd_special":"can't be tripped","sq":[{"type":"transparent"}],"environments":["any underground"],"organizations":["solitary"],"treasure":"incidental","description_visual":"Bits of broken weapons, coins, and a partially digested skeleton are visible inside this quivering cube of slime.","source":"PFRPG Bestiary","special_abilities":[{"type":"Acid","kind":"Ex","details":"A gelatinous cube's acid doesn't harm metal or stone."},{"type":"Engulf","kind":"Ex","details":"Although it moves slowly, a gelatinous cube can simply engulf Large or smaller creatures in its path as a standard action. It cannot make a slam attack during a round in which it engulfs. The gelatinous cube merely has to move over the opponents, affecting as many as it can cover. Opponents can make attacks of opportunity against the cube, but if they do so they are not entitled to a saving throw. Those who don't attempt attacks of opportunity can attempt a DC 12 Reflex save to avoid being engulfed-on a success, they are pushed back or aside (opponent's choice) as the cube moves forward. Engulfed creatures are subject to the cube's paralysis and acid, gain the pinned condition, are in danger of suffocating, and are trapped within its body until they are no longer pinned. The save DC is Strength-based."},{"type":"Paralysis","kind":"Ex","details":"A gelatinous cube secretes an anesthetizing slime. A target hit by a cube's melee or engulf attack must succeed on a DC 20 Fortitude save or be paralyzed for 3d6 rounds. The cube can automatically engulf a paralyzed opponent. The save DC is Constitution-based."},{"type":"Transparent","kind":"Ex","details":"Due to its lack of coloration, a gelatinous cube is difficult to discern. A DC 15 Perception check is required to notice a motionless gelatinous cube. Any creature that fails to notice a gelatinous cube and walks into it is automatically engulfed."}],"description":"One of the dungeon's most unusual and specialized predators, gelatinous cubes spend their existence mindlessly roaming dungeon halls and dark caverns, swallowing up organic material such as plants, refuse, carrion, and even living creatures. Materials the cube cannot digest, such as metal and stone, can eventually fill up the creature's mass with such detritus, and at times the creature may excrete some of this material out of its body. Often the treasure and possessions of past victims remain inside the gelatinous cube, leaving a ghostly impression of their material remains. Sages believe these creatures evolved as a specialized advancement of gray oozes. Some beings use gelatinous cubes as protectors of dungeons and underground fortifications, trapping the immense creatures in massive metal crates and transporting them through either slave power or magic to their final guard posts. They make particularly efficient waste disposal mechanisims as well-a tribe that can trap a gelatinous cube in a pit or other area that it cannot climb out of can use it as a midden or even a deadly trap, depending only on the ingenuity of the creatures who caught it. Gelatinous cubes are generally 10 ft. to a side and weigh upward of 15,000 pounds, though subterranean explorers report larger specimens trawling the deepest caves and corridors. In locations with plentiful sources of food, gelatinous cubes can exist for hundreds of years, if not thousands. However, if denied organic material for more than 6 months, a gelatinous cube begins shrinking. Eventually this stresses its walls and the creature leaks rapidly evaporating slimy liquid until its body collapses and disappears completely.","ecology":"","habitat_society":""},{"name":"Giant Assassin Bug","cr":3,"xp":800,"alignment":"N","size":"Small","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+2 Dex, +2 natural, +1 size","hp":27,"hd":"5d8+5","hdvalue":5,"fort":5,"ref":3,"will":4,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":30},{"type":"fly","speed":30,"maneuverability":"clumsy"}],"melee":"bite +6 (1d4+2 plus poison), 2 claws +6 (1d3+2)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"poison"},{"type":"poison stream"}],"strength":15,"dexterity":15,"constitution":13,"wisdom":10,"charisma":2,"baseatk":3,"cmb":8,"cmb_special":"+4 vs. grapple","cmd":21,"cmd_special":"+8 vs. trip","skills":[{"skill":"Fly","value":-4},{"skill":"Perception","value":4},{"skill":"Stealth","value":10}],"environments":["any warm"],"organizations":["solitary","nest (2-12)"],"treasure":"none","description_visual":"This goat-sized insect tilts its head to the side as it grinds its mouthparts in an intimidating trill.","group":"Assassin Bug","source":"AP 81","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 13; frequency 1/round for 4 rounds; effect 1d4 Dex; cure 2 consecutive saves. The save DC is Constitution-based."},{"type":"Poison Stream","kind":"Ex","details":"As a standard action usable every 1d4 rounds, an assassin bug can spray poison from its mouth in a 15-foot line. Any creature caught in this area must succeed at a DC 14 Reflex save to avoid being exposed to the assassin bug's poison. The save DC is Dexterity-based."}],"description":"Giant assassin bugs are an example of a large and varied class of hunting insects that live throughout Golarion. Assassin bugs partially bury themselves in the sand or hide among clusters of thorny bushes found near oases, waiting for the next palatable creature to approach. When prey arrives, the insects burst out of hiding and pierce their prey with their elongated mouthparts, injecting a potent toxin that paralyzes victims. Once prey is safely paralyzed, assassin bugs feed by siphoning the victim's fluids. Even if these bites don't kill their prey, they are extremely painful and cause swelling in the area.\n\nGiant assassin bugs lay eggs in places shaded from the sun at all times, such as shallow caves or the crevices between rocks, preferably in a place where food is readily available for the hatching young. The soft-bodied young that hatch resemble their mature counterparts in all ways but size, and are fully ready to hunt the moment they emerge, though they typically seek much smaller prey. An adult assassin bug is typically 4 ft. long, and weighs 65 pounds.","ecology":"","habitat_society":""},{"name":"Giant Black Widow Spider","cr":3,"xp":800,"alignment":"N","size":"Large","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":15,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+2 Dex, +4 natural, -1 size","hp":37,"hd":"5d8+15","hdvalue":5,"fort":7,"ref":3,"will":1,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":30}],"melee":"bite +6 (1d8+6 plus poison)","space":"10 ft.","reach":"5 ft.","special_attacks":[{"type":"web","details":"+4 ranged, DC 19, 5 hp"}],"strength":19,"dexterity":15,"constitution":16,"wisdom":10,"charisma":2,"baseatk":3,"cmb":8,"cmd":20,"cmd_special":"+12 vs. trip","skills":[{"skill":"Climb","value":20},{"skill":"Perception","value":4}],"sq":[{"type":"strong webs"}],"environments":["any land"],"organizations":["solitary","pair","colony (3-8)"],"treasure":"incidental","description_visual":"This long-legged spider has a huge, glossy black abdomen, marked on the underside with the shape of a crimson hourglass.","group":"Spider","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Poison","kind":"Ex","details":"Bite- injury; save Fort DC 17; frequency 1/ round for 6 rounds; effect 1d3 Con and staggered; cure 2 saves. Save DC is Con-based with a +2 racial bonus."},{"type":"Strong Webs","kind":"Ex","details":"A black widow's webs gain a +4 bonus to the DC to break or escape."}],"description":"Females of this species are larger than males.\n\nMales are identical to the typical giant spider.","ecology":"","habitat_society":""},{"name":"Giant Chameleon","cr":3,"xp":800,"alignment":"N","size":"Large","type":"animal","init":6,"senses":[{"type":"low-light vision"}],"ac":14,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+2 Dex, +3 natural, -1 size","hp":34,"hd":"4d8+16","hdvalue":4,"fort":8,"ref":6,"will":1,"speed":[{"type":"land","speed":40},{"type":"climb","speed":40}],"melee":"bite +5 (2d6+4) or tongue +5 touch (grab)","space":"10 ft.","reach":"10 ft. (15 ft. with tongue)","special_attacks":[{"type":"tongue"},{"type":"pull","details":"tongue, 5 ft."}],"strength":16,"dexterity":15,"constitution":18,"intelligence":2,"wisdom":11,"charisma":7,"baseatk":3,"cmb":7,"cmb_special":"+4 vs. grapple","cmd":19,"cmd_special":"+4 vs. trip","feats":[{"feat":"Improved Initiative"},{"feat":"Skill Focus (Stealth)"}],"skills":[{"skill":"Climb","value":15},{"skill":"Perception","value":4},{"skill":"Stealth","value":18,"special":"+28 when still"}],"environments":["warm forests","warm mountains"],"organizations":["solitary","pair","blend (3-6)"],"treasure":"none","description_visual":"Nearly invisible in its surroundings, this scaly lizard's eyes dart about independently of each other.","group":"Lizard","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Tongue","kind":"Ex","details":"A giant chameleon can grab a foe with its tongue and draw the victim to its mouth. This tongue attack has a reach of 15 ft. The attack does no damage, but allows the creature to grab. A giant chameleon doesn't gain the grappled condition while using its tongue in this manner."}],"description":"These large lizards have the ability to shift the pigments in their skin to match their surroundings. A giant chameleon is typically 11 ft. long and weighs 160 pounds.","ecology":"","habitat_society":""},{"name":"Giant Dragonfly Nymph","cr":3,"xp":800,"alignment":"N","size":"Small","type":"vermin","subtypes":["aquatic"],"init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+1 Dex, +3 natural, +1 size","hp":32,"hd":"5d8+10","hdvalue":5,"fort":6,"ref":2,"will":2,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":10},{"type":"swim","speed":30}],"melee":"bite +6 (2d6+3)","space":"5 ft.","reach":"5 ft. (10 ft. with bite)","special_attacks":[{"type":"extending jaw"}],"strength":15,"dexterity":13,"constitution":14,"wisdom":12,"charisma":5,"baseatk":3,"cmb":4,"cmd":15,"cmd_special":"+8 vs. trip","skills":[{"skill":"Stealth","value":5,"special":"+13 in shallow water"},{"skill":"Swim","value":10}],"environments":["temperate water","warm water"],"organizations":["solitary","pair","brood (3-8)"],"treasure":"incidental","description_visual":"This glittering blue dragonfly is about the size of a horse and is large enough to carry off small farm animals or people.","group":"Dragonfly","source":"PFRPG Bestiary 2","special_abilities":[{"type":"Extending Jaw","kind":"Ex","details":"A giant dragonfly nymph can extend its jaws with surprising speed. Not only does this extend the nymph's reach with its bite attack, but during the surprise round, a nymph gains a +4 bonus on attack rolls with its bite."}],"description":"Giant dragonf lies lay clutches of eggs in swampy terrain or areas of standing water. Their young, called nymphs, voraciously eat carrion and small prey, growing and maturing rapidly until they sprout fully functional wings and become adult dragonf lies.","ecology":"","habitat_society":""},{"name":"Giant Eagle","cr":3,"xp":800,"alignment":"NG","size":"Large","type":"magical beast","init":3,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":12,"ac_flat_footed":12,"ac_mods":"+3 Dex, +3 natural, -1 size","hp":26,"hd":"4d10+4","hdvalue":4,"fort":5,"ref":7,"will":3,"defensive_abilities":["evasion"],"speed":[{"type":"land","speed":10},{"type":"fly","speed":80,"maneuverability":"average"}],"melee":"2 claws +7 (1d8+4), bite +7 (1d6+4)","space":"10 ft.","reach":"5 ft.","strength":18,"dexterity":17,"constitution":12,"intelligence":10,"wisdom":15,"charisma":11,"baseatk":4,"cmb":9,"cmd":22,"feats":[{"feat":"Alertness"},{"feat":"Flyby Attack"}],"skills":[{"skill":"Fly","value":8},{"skill":"Perception","value":15},{"skill":"Sense Motive","value":4}],"languages":["Auran (cannot speak)"],"environments":["temperate mountains"],"organizations":["solitary","pair","eyrie (3-12)"],"treasure":"none","description_visual":"This immense eagle's feathers are golden brown and shimmer in the light. Its sharp beak and curved talons are dark yellow.","group":"Eagle","source":"PFRPG Bestiary","description":"A typical giant eagle stands about 15 ft. tall, has a wingspan of up to 30 ft., and resembles its smaller cousins in nearly every way except size. It weighs 500 pounds.","ecology":"","habitat_society":""},{"name":"Giant Locust","cr":3,"xp":800,"alignment":"N","size":"Medium","type":"vermin","init":2,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+2 Dex, +5 natural","hp":22,"hd":"4d8+4","hdvalue":4,"fort":5,"ref":3,"will":1,"immunities":["mind-affecting effects"],"resists":[{"type":"acid","value":5}],"speed":[{"type":"land","speed":20},{"type":"climb","speed":20},{"type":"fly","speed":60,"maneuverability":"average"}],"melee":"bite +6 (1d8+4)","ranged":"spit +5 touch (1d3 acid)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"voracious"}],"strength":16,"dexterity":15,"constitution":13,"wisdom":10,"charisma":7,"baseatk":3,"cmb":6,"cmd":18,"cmd_special":"+8 vs. trip","skills":[{"skill":"Acrobatics","value":2,"special":"+20 jumping"},{"skill":"Climb","value":11}],"sq":[{"type":"leap"}],"environments":["temperate deserts","temperate plains","warm deserts","warm plains"],"organizations":["solitary","pair","gang (3-8)","colony (5-20)"],"treasure":"none","description_visual":"The mandibles of this enormous grasshopper churn and grind as it quests for food.","group":"Locust","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Leap","kind":"Ex","details":"A giant locust can take 10 on Acrobatics checks to jump even if distracted or in danger."},{"type":"Spit","kind":"Ex","details":"A giant locust can spit a brown jet of acid and partially digested food up to 30 ft. with no range increment."},{"type":"Voracious","kind":"Ex","details":"A giant locust's bite attack deals double damage to creatures with the plant subtype and to objects made of paper, wood, or other plant materials."}],"description":"Giant locusts have a hunger akin to their smaller cousins, but only rarely do they gather in the endless numbers of their tiny kin. A mature giant locust measures just over 4 ft. long and weighs 50 pounds.","ecology":"","habitat_society":""},{"name":"Giant Mantis","cr":3,"xp":800,"alignment":"N","size":"Large","type":"vermin","init":1,"senses":[{"type":"darkvision","modifier":"60 ft."}],"ac":15,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+1 Dex, +5 natural, -1 size","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":2,"will":3,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":30},{"type":"climb","speed":30},{"type":"fly","speed":40,"maneuverability":"poor"}],"melee":"2 claws +5 (1d6+3 plus grab)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"lunge"},{"type":"mandibles"},{"type":"sudden strike"}],"strength":16,"dexterity":13,"constitution":16,"wisdom":14,"charisma":11,"baseatk":3,"cmb":7,"cmb_special":"+4 vs. grapple","cmd":18,"cmd_special":"+4 vs. trip","skills":[{"skill":"Climb","value":11},{"skill":"Fly","value":-5},{"skill":"Perception","value":6},{"skill":"Stealth","value":1,"special":"+13 in forests"}],"environments":["temperate forests"],"organizations":["solitary"],"treasure":"none","description_visual":"This towering insect walks on its back four legs. Its head is triangular and its front legs sport razor-sharp edges and claws.","group":"Mantis","source":"PFRPG Bestiary","special_abilities":[{"type":"Lunge","kind":"Ex","details":"A giant mantis's limbs are capable of reaching much farther than normal for a creature of its size. As a full attack action, it can make a single attack with its claws at double its normal reach. When a giant mantis attacks with a claw in this manner, it gains a +4 bonus on its attack roll. A giant mantis cannot make attacks of opportunity with its lunge."},{"type":"Mandibles","kind":"Ex","details":"A giant mantis that grabs a foe can make a bite attack against that foe as a secondary attack. The mantis's bite is a +0 attack that inflicts 1d6+1 points of damage on a hit."},{"type":"Sudden Strike","kind":"Ex","details":"A giant mantis is particularly adept at moving quickly when its foes are surprised. During a surprise round, a giant mantis may act as if it had a full round to act, rather than just one standard action."}],"description":"Known to many as the giant praying mantis for the way the creature's deadly front limbs fold under its head as it lies in wait for food, this creature is well feared along caravan tracks that pass through dense woodlands. The giant mantis, a master of hiding in dense undergrowth, is almost unnaturally patient as it lies in wait, striking with unsettling speed as unsuspecting meals wander by.\n\nIn many savage societies, the giant mantis is particularly feared-in regions where these vermin are common, they are often regarded as messengers of death sent to the world by angry gods. Their swift speed, alien appearance, and near-invisibility in forests give rise to many legends- that the giant mantis can become invisible, that it can smell fear, and that the souls of those who it slays and eats are digested and kept from moving on to the afterlife.\n\nWhile the giant mantis isn'thing more than an efficient and deadly vermin, the numerous legends and whispers regarding its supposed powers and alien intellect have inspired some spellcasters to work such features into their constructs as a way to make them even more fearsome. There are even stories of entire societies of assassins who worship an immense mantis as a god, and who have taken to heart the mantis's style of murderous ambush, fighting with twin serrated rapiers.\n\nThe giant mantis presented here stands 7 ft. tall and 15 ft. long, and weighs 650 pounds. Larger giant mantises exist in the deepest, darkest forests of the world, where they might prey upon things as mighty as giants or dragons. Known by various names, such as the drake eating mantis, the treebender mantis, or simply the deadly mantis, these immense behemoths average more than 60 ft. in height and have a terrifying habit of destroying entire villages or towns in order to satiate their ravenous appetites. A deadly mantis is a giant mantis advanced to Colossal size, 16 Hit Dice, and CR 14.","ecology":"","habitat_society":""},{"name":"Giant Rot Grub","cr":3,"xp":800,"alignment":"N","size":"Small","type":"vermin","init":1,"senses":[{"type":"blindsense","modifier":"30 ft."}],"ac":15,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+1 Dex, +3 natural, +1 size","hp":34,"hd":"4d8+16","hdvalue":4,"fort":8,"ref":2,"will":1,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":20}],"melee":"bite +6 (1d6+3 plus poison and grab)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"gnaw"},{"type":"grab","details":"Medium"}],"strength":14,"dexterity":12,"constitution":18,"wisdom":10,"charisma":1,"baseatk":3,"cmb":4,"cmb_special":"+4 vs. grapple","cmd":15,"environments":["any"],"organizations":["solitary","pair","nest (3-8)"],"treasure":"none","description_visual":"This twitching, pale maggot is the size of a large dog. A circular mouth quivers and gasps at one end of its pulsating body.","group":"Parasite","source":"PFRPG Bestiary 3","special_abilities":[{"type":"Gnaw","kind":"Ex","details":"A rot grub that is grappling a foe and chooses to damage the foe with an additional grapple check deals twice its normal bite damage (2d6+6 for most giant rot grubs), in addition to injecting an additional dose of poison with each successful check."},{"type":"Poison","kind":"Ex","details":"Bite-injury; save Fort DC 16; frequency 1/round for 5 rounds; effect 1d3 Str; cure 1 save."}],"description":"Rot grubs are foul, nauseating parasites that feed on flesh and use corpses as nests in which to grow. While a rot grub can derive nourishment from dead flesh, its true hunger is for the flesh of the living. Thankfully, rot grub swarms occur only rarely, as they require the infested carcass of a Huge or larger creature and many weeks to build up the numbers necessary to constitute a swarm.\n\nIn some cases, a rot grub continues to feed and grow, eventually reaching enormous size as a giant rot grub.","ecology":"","habitat_society":""},{"name":"Giant Scorpion","cr":3,"xp":800,"alignment":"N","size":"Large","type":"vermin","init":0,"senses":[{"type":"darkvision","modifier":"60 ft."},{"type":"tremorsense","modifier":"60 ft."}],"ac":16,"ac_touch":9,"ac_flat_footed":16,"ac_mods":"+7 armor, -1 size","hp":37,"hd":"5d8+15","hdvalue":5,"fort":7,"ref":1,"will":1,"immunities":["mind-affecting effects"],"speed":[{"type":"land","speed":50}],"melee":"2 claws +6 (1d6+4 plus grab), sting +6 (1d6+4 plus poison)","space":"10 ft.","reach":"10 ft.","special_attacks":[{"type":"constrict","details":"1d6+4"}],"strength":19,"dexterity":10,"constitution":16,"wisdom":10,"charisma":2,"baseatk":3,"cmb":8,"cmb_special":"+4 vs. grapple","cmd":18,"cmd_special":"+12 vs. trip","skills":[{"skill":"Climb","value":8},{"skill":"Perception","value":4},{"skill":"Stealth","value":0}],"environments":["any forests","any plains","temperate deserts","any underground","warm deserts"],"organizations":["solitary"],"treasure":"none","description_visual":"The sixteen-foot-long scorpion scrabbles forward, ferocious claws raised in challenge, stingered tail arched over its back.","group":"Scorpion","source":"PFRPG Bestiary","special_abilities":[{"type":"Poison","kind":"Ex","details":"Sting-injury; save Fort DC 17; frequency 1/round for 6 rounds; effect 1d2 Strength damage; cure 1 save. The save DC is Constitutuion-based and includes a +2 racial bonus."}],"description":"Giant scorpions are monstrous versions of the more common desert scorpion. They are likely to attack any creature that approaches. Giant scorpions usually charge when attacking, grabbing prey in their pincers, then lashing their segmented tails forward to kill their victim with injected venom. Giant scorpions are just over 8 ft. long from head to the base of the tail; the tail adds an additional 8 ft. or so, although it is usually curled up over the scorpion's back. Giant scorpions weigh between 2,000 and 6,000 pounds. Giant scorpions normally feed on other giant vermin, as well as large mammals that they paralyze with their venom, but they will attack and eat any living creature that ventures too close. In turn, giant scorpions are preyed upon by purple worms and other large predators. Giant scorpions engage in complex courtship rituals when they mate, grasping each other's pincers, arching their tails, and performing a circular \"dance.\" Soon after mating, the male usually retreats to avoid being cannibalized by the female. Female scorpions don't lay eggs; they give birth to live young in broods of a dozen or so. The mother carries her brood on her back until the young are old enough to fend for themselves and hunt their own prey. Giant scorpions live in underground burrows, either as solitary hunters or in small colonies, and will sometimes take up residence in man-made ruins or dungeons if food is plentiful. Giant scorpion colonies are usually made up of scorpions from the same brood that have yet to strike out on their own. Other species of scorpions exist as well, some smaller but most quite a bit larger and favoring different terrains, such as forests, plains, or even underground. You can adjust the stats for the giant scorpion by changing Hit Dice and size (adjusting Strength, Dexterity, and Constitution as appropriate) to represent a wide range of species. The following table lists the most common variants. Species CR Size HD Greensting scorpion 1/4 Tiny 1d8 Ghost scorpion 1/2 Small 2d8 Cave scorpion 1 Medium 3d8 Deadfall scorpion 8 Huge 10d8 Giant emperor scorpion 11 Gargantuan 16d8 Black scorpion 15 Colossal 22d8.","ecology":"","habitat_society":""},{"name":"Giant Seahorse","cr":3,"xp":800,"alignment":"N","size":"Large","type":"animal","subtypes":["aquatic"],"init":2,"senses":[{"type":"low-light vision"}],"ac":15,"ac_touch":11,"ac_flat_footed":13,"ac_mods":"+4 armor, +2 Dex, -1 size","hp":30,"hd":"4d8+12","hdvalue":4,"fort":7,"ref":6,"will":2,"defensive_abilities":["anchor"],"speed":[{"type":"swim","speed":30}],"melee":"slam +7 (1d6+7)","space":"10 ft.","reach":"5 ft.","strength":20,"dexterity":14,"constitution":17,"intelligence":1,"wisdom":12,"charisma":7,"baseatk":3,"cmb":9,"cmd":21,"feats":[{"feat":"Endurance"},{"feat":"Skill Focus (Perception)"}],"skills":[{"skill":"Perception","value":11},{"skill":"Swim","value":13}],"environments":["any oceans"],"organizations":["solitary","pair","school (3-20)"],"treasure":"none","description_visual":"This sea creature resembles a cross between fish and horse; it has small fins on its flanks and a gracefully curled tail.","group":"Seahorse","source":"PFRPG Bestiary 4","special_abilities":[{"type":"Anchor","kind":"Ex","details":"As a move action, a seahorse can wrap its tail around a stationary object. The seahorse remains anchored to the object until it releases its grip (a free action) or is forcibly moved. An anchored seahorse gains a +4 bonus to its combat maneuver defense and on checks and saving throws against effects that would move it against its will."}],"description":"Giant seahorses are bear-sized versions of the common, harmless seahorse. Naturally docile and skittish, seahorses are easily trained to be mounts but are difficult to train for combat. They provide a smoother but slower ride than sharks or hippocampi. A giant seahorse is considered a quadruped for the purpose of carrying capacity. A light load for a giant seahorse is up to 500 pounds, a medium load is 1,000 pounds, and a heavy load is 1,600 pounds. It can drag 8,000 pounds.","ecology":"","habitat_society":""}];
